PRAGMA foreign_keys=ON;
CREATE TABLE Owner(owner_id TEXT PRIMARY KEY, owner_name TEXT NOT NULL, owner_type TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)));
CREATE TABLE Location(location_id TEXT PRIMARY KEY, location_name TEXT NOT NULL, city TEXT NOT NULL, country TEXT NOT NULL, location_type TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)));
CREATE TABLE AssetType(asset_type_id TEXT PRIMARY KEY, type_code TEXT UNIQUE NOT NULL, description TEXT NOT NULL, return_sla_days INTEGER NOT NULL CHECK(return_sla_days>0), loss_threshold_days INTEGER NOT NULL CHECK(loss_threshold_days>0), deposit_amount REAL NOT NULL CHECK(deposit_amount>=0), repair_sla_days INTEGER NOT NULL CHECK(repair_sla_days>0), active INTEGER NOT NULL);
CREATE TABLE ReusableAsset(asset_id TEXT PRIMARY KEY, asset_type_id TEXT NOT NULL REFERENCES AssetType, owner_id TEXT NOT NULL REFERENCES Owner, serial_number TEXT UNIQUE NOT NULL, created_at TEXT NOT NULL, current_status TEXT NOT NULL, home_location_id TEXT NOT NULL REFERENCES Location, deposit_amount REAL NOT NULL CHECK(deposit_amount>=0), is_active INTEGER NOT NULL);
CREATE TABLE Shipment(shipment_id TEXT PRIMARY KEY, origin_location_id TEXT NOT NULL REFERENCES Location, destination_location_id TEXT NOT NULL REFERENCES Location, carrier_owner_id TEXT NOT NULL REFERENCES Owner, dispatch_at TEXT NOT NULL, expected_delivery_at TEXT NOT NULL, shipment_status TEXT NOT NULL, tracking_reference TEXT UNIQUE NOT NULL);
CREATE TABLE ShipmentAsset(shipment_id TEXT NOT NULL REFERENCES Shipment, asset_id TEXT NOT NULL REFERENCES ReusableAsset, quantity INTEGER NOT NULL CHECK(quantity>0), PRIMARY KEY(shipment_id,asset_id));
CREATE TABLE CustodyEvent(custody_event_id TEXT PRIMARY KEY, asset_id TEXT NOT NULL REFERENCES ReusableAsset, shipment_id TEXT REFERENCES Shipment, event_type TEXT NOT NULL, event_at TEXT NOT NULL, from_location_id TEXT REFERENCES Location, to_location_id TEXT REFERENCES Location, actor_owner_id TEXT REFERENCES Owner, notes TEXT, issue_type TEXT);
CREATE TABLE ReturnAuthorization(rma_id TEXT PRIMARY KEY, asset_id TEXT NOT NULL REFERENCES ReusableAsset, requested_at TEXT NOT NULL, authorized_at TEXT, received_at TEXT, return_status TEXT NOT NULL, source_location_id TEXT NOT NULL REFERENCES Location, destination_location_id TEXT NOT NULL REFERENCES Location, reason TEXT);
CREATE TABLE Inspection(inspection_id TEXT PRIMARY KEY, rma_id TEXT NOT NULL REFERENCES ReturnAuthorization, asset_id TEXT NOT NULL REFERENCES ReusableAsset, inspected_at TEXT NOT NULL, inspector_owner_id TEXT NOT NULL REFERENCES Owner, result TEXT NOT NULL, damage_cost REAL NOT NULL CHECK(damage_cost>=0), notes TEXT);
CREATE TABLE Repair(repair_id TEXT PRIMARY KEY, asset_id TEXT NOT NULL REFERENCES ReusableAsset, inspection_id TEXT REFERENCES Inspection, opened_at TEXT NOT NULL, closed_at TEXT, repair_status TEXT NOT NULL, repair_cost REAL NOT NULL CHECK(repair_cost>=0), repair_center_location_id TEXT NOT NULL REFERENCES Location);
CREATE TABLE DepositLedger(ledger_entry_id TEXT PRIMARY KEY, asset_id TEXT NOT NULL REFERENCES ReusableAsset, rma_id TEXT REFERENCES ReturnAuthorization, entry_type TEXT NOT NULL, amount REAL NOT NULL CHECK(amount>=0), currency TEXT NOT NULL, posted_at TEXT NOT NULL, reference TEXT NOT NULL);
